'use strict';

// MODULES //

var tape = require( 'tape' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var factory = require( './../lib/factory.js' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a function', function test( t ) {
	var mgf = factory( 0.0, 1.0 );
	t.strictEqual( typeof mgf, 'function', 'returns expected value' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the created function returns `NaN`', function test( t ) {
	var mgf;
	var y;

	mgf = factory( 20, 0.5 );
	y = mgf( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( NaN, 0.5 );
	y = mgf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( 20, NaN );
	y = mgf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( NaN, NaN );
	y = mgf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( NaN, NaN );
	y = mgf( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a `r` which is not a positive number, the created function always returns `NaN`', function test( t ) {
	var mgf;
	var y;

	mgf = factory( -10.0, 0.5 );

	y = mgf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( -4.0, 0.5 );
	y = mgf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( NINF, 0.5 );
	y = mgf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a success probability `p` outside `[0,1]`, the created function always returns `NaN`', function test( t ) {
	var mgf;
	var y;

	mgf = factory( 20.0, 1.5 );

	y = mgf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( 20.0, -0.5 );
	y = mgf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( 20.0, PINF );
	y = mgf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( 20.0, NINF );
	y = mgf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the created function returns `NaN` if provided `t >= -ln( 1-p )`', function test( t ) {
	var mgf;
	var y;

	mgf = factory( 10, 0.5 ); // -ln( 1-p ) = ~0.693
	y = mgf( 0.7 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( 10, 0.2 ); // -ln( 1-p ) = ~0.223
	y = mgf( 1.7 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	t.end();
});

tape( 'the created function evaluates the mgf', function test( t ) {
	var expected;
	var mgf;
	var r;
	var p;
	var x;
	var y;
	var i;

	expected = data.expected;
	x = data.t;
	r = data.r;
	p = data.p;
	for ( i = 0; i < x.length; i++ ) {
		mgf = factory( r[ i ], p[ i ] );
		y = mgf( x[ i ] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 40 ), true, 'returns expected value' );
	}
	t.end();
});
